   524→    const s = stmt as any;
   525→
   526→    if (s.type === 'Return') {
   527→      const returnStmt = s as AST.ReturnStatement;
   528→      if (returnStmt.value) {
   529→        const expr = this.genVExpression(returnStmt.value);
   530→        this.writeC(`${this.indent()}return ${expr};`);
   531→      } else {
   532→        this.writeC(`${this.indent()}return;`);
   533→      }
   534→    } else if (s.type === 'Break') {
   535→      this.writeC(`${this.indent()}break;`);
   536→    } else if (s.type === 'Continue') {
   537→      this.writeC(`${this.indent()}continue;`);
   538→    } else if (s.type === 'Assign') {
   539→      const assignStmt = s as AST.AssignStatement;
   540→      const value = assignStmt.value as any;
   541→      const varName = assignStmt.name;
   542→
   543→      // 현재 스코프(또는 상위 스코프)에서 이미 선언된 변수인지 확인
   544→      const alreadyDeclared = this.declaredVars.some(scope => scope.has(varName));
   545→
   546→      if (alreadyDeclared) {
   547→        // 재할당: 타입 선언 없이 그냥 대입
   548→        const expr = this.genVExpression(assignStmt.value);
   549→        this.writeC(`${this.indent()}${varName} = ${expr};`);
   550→      } else {
   551→        // 최초 선언: 현재 스코프에 등록
   552→        this.declaredVars[this.declaredVars.length - 1].add(varName);
   553→
   554→        // 명시적 타입 어노테이션이 있는 경우
   555→        if (assignStmt.typeAnnotation) {
   556→          const ta = assignStmt.typeAnnotation;
   557→          if (ta.endsWith('[]')) {
   558→            const elemType = this.mapVType(ta.slice(0, -2));
   559→            const expr = this.genVExpression(assignStmt.value);
   560→            if (value.type === 'Array') {
   561→              const len = (value as AST.ArrayLiteral).elements.length;
   562→              this.writeC(`${this.indent()}${elemType} ${varName}[${len}] = ${expr};`);
   563→            } else {
   564→              this.writeC(`${this.indent()}${elemType}* ${varName} = ${expr};`);
   565→            }
   566→          } else {
   567→            const cType = this.mapVType(ta);
   568→            const expr = this.genVExpression(assignStmt.value);
   569→            this.writeC(`${this.indent()}${cType} ${varName} = ${expr};`);
   570→          }
   571→        } else {
   572→          // 타입 추론: 값 기반
   573→          const expr = this.genVExpression(assignStmt.value);
   574→          let cType = 'long long';
   575→          if (value.type === 'String') {
   576→            cType = 'char*';
   577→          } else if (value.type === 'Array') {
   578→            const arrLit = value as AST.ArrayLiteral;
   579→            const firstElem = arrLit.elements[0] as any;
   580→            let elemType = 'long long';
   581→            if (firstElem?.type === 'String') elemType = 'char*';
   582→            else if (firstElem?.type === 'Number' && String(firstElem.value).includes('.')) elemType = 'double';
   583→            const len = arrLit.elements.length;
   584→            this.writeC(`${this.indent()}${elemType} ${varName}[${len}] = ${expr};`);
   585→            return;
   586→          } else if (value.type === 'Number' && String(value.value).includes('.')) {
   587→            cType = 'double';
   588→          } else if (value.type === 'StructLiteral') {
   589→            // struct 리터럴 → struct 타입명 사용
   590→            cType = (value as AST.StructLiteral).name;
   591→          }
   592→          this.writeC(`${this.indent()}${cType} ${varName} = ${expr};`);
   593→        }
   594→      }
   595→    } else if (s.type === 'ExprStatement') {
   596→      const exprStmt = s as AST.ExprStatement;
   597→      const expr = this.genVExpression(exprStmt.expression);
   598→      this.writeC(`${this.indent()}${expr};`);
   599→    } else if (s.type === 'IfStatement') {
   600→      const ifStmt = s as AST.IfStatement;
   601→      const cond = this.genVExpression(ifStmt.condition);
   602→      this.writeC(`${this.indent()}if (${cond}) {`);
   603→      this.indentLevel++;
   604→      this.declaredVars.push(new Set());
   605→      for (const stmt of ifStmt.thenBranch) {
   606→        this.genVStatement(stmt);
   607→      }
   608→      this.declaredVars.pop();
   609→      this.indentLevel--;
   610→      this.writeC(`${this.indent()}}`);
   611→      if (ifStmt.elseBranch) {
   612→        this.writeC(`${this.indent()}else {`);
   613→        this.indentLevel++;
   614→        this.declaredVars.push(new Set());
   615→        for (const stmt of ifStmt.elseBranch) {
   616→          this.genVStatement(stmt);
   617→        }
   618→        this.declaredVars.pop();
   619→        this.indentLevel--;
   620→        this.writeC(`${this.indent()}}`);
   621→      }
   622→    } else if (s.type === 'WhileStatement') {
   623→      const whileStmt = s as AST.WhileStatement;
   624→      const cond = this.genVExpression(whileStmt.condition);
   625→      this.writeC(`${this.indent()}while (${cond}) {`);
   626→      this.indentLevel++;
   627→      this.declaredVars.push(new Set());
   628→      for (const stmt of whileStmt.body) {
   629→        this.genVStatement(stmt);
   630→      }
   631→      this.declaredVars.pop();
   632→      this.indentLevel--;
   633→      this.writeC(`${this.indent()}}`);
   634→    } else if (s.type === 'ForStatement') {
   635→      const forStmt = s as AST.ForStatement;
   636→      const iterExpr = forStmt.iterable as any;
   637→
   638→      // range(n) CallExpr 케이스
   639→      if (iterExpr.type === 'Call') {
   640→        const callee = iterExpr.callee as any;
   641→        const calleeName = callee.type === 'Identifier' ? callee.name : '';
   642→        if (calleeName === 'range' && iterExpr.args.length === 1) {
   643→          const limit = this.genVExpression(iterExpr.args[0]);
   644→          this.writeC(`${this.indent()}for (long long ${forStmt.variable} = 0; ${forStmt.variable} < ${limit}; ${forStmt.variable}++) {`);
   645→        } else {
   646→          const iterStr = this.genVExpression(forStmt.iterable);
   647→          this.writeC(`${this.indent()}for (long long ${forStmt.variable} = 0; ${forStmt.variable} < ${iterStr}; ${forStmt.variable}++) {`);
   648→        }
   649→      } else {
   650→        const iterStr = this.genVExpression(forStmt.iterable);
   651→        this.writeC(`${this.indent()}for (long long ${forStmt.variable} = 0; ${forStmt.variable} < sizeof(${iterStr})/sizeof(${iterStr}[0]); ${forStmt.variable}++) {`);
   652→      }
   653→
   654→      this.indentLevel++;
   655→      this.declaredVars.push(new Set([forStmt.variable]));
   656→      for (const stmt of forStmt.body) {
   657→        this.genVStatement(stmt);
   658→      }
   659→      this.declaredVars.pop();
   660→      this.indentLevel--;
   661→      this.writeC(`${this.indent()}}`);
   662→    } else if (s.type === 'MatchStatement') {
   663→      // match x { case 1 => { ... } case _ => { ... } }
   664→      // → switch (x) { case 1: { ... break; } default: { ... break; } }
   665→      const matchStmt = s as AST.MatchStatement;
   666→      const subj = this.genVExpression(matchStmt.subject);
   667→      this.writeC(`${this.indent()}switch (${subj}) {`);
   668→      this.indentLevel++;
   669→      for (const arm of matchStmt.arms) {
   670→        if (arm.pattern === null) {
   671→          this.writeC(`${this.indent()}default: {`);
   672→        } else {
   673→          const pat = this.genVExpression(arm.pattern);
   674→          this.writeC(`${this.indent()}case ${pat}: {`);
   675→        }
   676→        this.indentLevel++;
   677→        this.declaredVars.push(new Set());
   678→        for (const stmt of arm.body) {
   679→          this.genVStatement(stmt);
   680→        }
   681→        this.writeC(`${this.indent()}break;`);
   682→        this.declaredVars.pop();
   683→        this.indentLevel--;
   684→        this.writeC(`${this.indent()}}`);
   685→      }
   686→      this.indentLevel--;
   687→      this.writeC(`${this.indent()}}`);
   688→    }
   689→  }
