    __fl_py_ensure_init();
    __fl_py_mod_np = PyImport_ImportModule("numpy");
    if (!__fl_py_mod_np) { PyErr_Print(); fprintf(stderr, "Failed: numpy\n"); }
}

int main() {
    long long x = __fl_py_to_ll(PyObject_CallMethod(__fl_py_mod_np, "add", "LL", (long long)(2), (long long)(3)));
    printf("%lld\n", x);
    return 0;
}

__attribute__((constructor))
static void __fl_py_auto_init(void) { __fl_py_init_np(); }
__attribute__((destructor))
static void __fl_py_auto_fini(void) { Py_Finalize(); }

